#!/usr/bin/env python3
"""Generate the K String constant used to model CPython's str.isalpha()."""

import sys


def k_escape(codepoint):
    if codepoint <= 0xFFFF:
        return f"\\u{codepoint:04x}"
    return f"\\U{codepoint:08x}"


letters = "".join(
    k_escape(codepoint)
    for codepoint in range(sys.maxunicode + 1)
    if chr(codepoint).isalpha()
)

with open("python-alpha-data.k", "w", encoding="ascii") as output:
    output.write('requires "domains.md"\n\n')
    output.write("module PYTHON-ALPHA-DATA\n")
    output.write("  imports STRING\n\n")
    output.write("  syntax String ::= pythonAlphabet() [function]\n")
    output.write(f'  rule pythonAlphabet() => "{letters}"\n')
    output.write("endmodule\n")

